import axios from 'axios';
import { Blog } from './blog.types';
import { API_BASE_URL } from '@/shared/api';

interface blogState {
    blogData: Blog[];
    searchResults: Blog[];
}

export const blogModule = {
    namespaced: true,
    state: (): blogState => ({
        blogData: [],
        searchResults: [],
    }),
    mutations: {
        setBlog(state: blogState, blogs: Blog[]) {
            state.blogData = blogs;
        },
     
        
    },
    actions: {
        async fetchBlog({ commit }: { commit: Function }) {
            try {
                const response = await axios.get<Blog[]>(`${API_BASE_URL}blogs`);
                const blogs: Blog[] = response.data;
                commit('setBlog', blogs);
            } catch (error) {
                console.error('Ошибка при получении данных:', error);
            }
        },
    }
}
