import axios from 'axios';
import { Projects } from './projects.types';
import { API_BASE_URL } from '@/shared/api';

interface ProjectsState {
    projectsData: Projects[];
    searchResults: Projects[];
}

export const projectsModule = {
    namespaced: true,
    state: (): ProjectsState => ({
        projectsData: [],
        searchResults: [],
    }),
    mutations: {
        setProjects(state: ProjectsState, projects: Projects[]) {
            state.projectsData = projects;
        },
     
        
    },
    actions: {
        async fetchProjects({ commit }: { commit: Function }) {
            try {
                const response = await axios.get<Projects[]>(`${API_BASE_URL}projects`);
                const projects: Projects[] = response.data;
                commit('setProjects', projects);
            } catch (error) {
                console.error('Ошибка при получении данных:', error);
            }
        },
    }, 
    getters: {
        getProjectsBySlug: (state: ProjectsState) => (slug: string) => {
            return state.projectsData.find(projects => projects.slug === slug);
        },
    }
}
